export type FigmaIconName = keyof typeof FIGMA_ICONS;

/**
 * One Figma icon, drawn at its natural size unless told otherwise.
 *
 * `currentColor` throughout, so the rail's `color` drives it and dark mode
 * needs no second asset.
 */
export function FigmaIcon({ name, size, className }: {
	name: string;
	/** Overrides the natural size, scaling both axes by the same factor. */
	size?: number;
	className?: string;
}) {
	const def = FIGMA_ICONS[name];
	if (!def) return null;
	const scale = size ? size / Math.max(def.w, def.h) : 1;
	return (
		<svg
			viewBox={def.viewBox}
			width={Math.round(def.w * scale * 100) / 100}
			height={Math.round(def.h * scale * 100) / 100}
			className={className}
			aria-hidden="true"
			focusable="false"
		>
			{def.paint}
		</svg>
	);
}
